let progress={};try{progress=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const done=new Set(Array.isArray(progress.done)?progress.done:[]);
